using System;
using System.Threading;
using System.Threading.Tasks;

public class ReportGenerator
{
    public async Task GenerateHeavyReportAsync(CancellationToken ct)
    {
        Console.WriteLine("[Report] Memulai pembuatan laporan 10 batch...");

        for (int i = 1; i <= 10; i++)
        {
            // Lempar OperationCanceledException jika client membatalkan request
            ct.ThrowIfCancellationRequested();

            await Task.Delay(100, ct);
            Console.WriteLine($"[Report] Menyelesaikan batch {i}/10");
        }

        Console.WriteLine("[Report] Selesai 100%!");
    }
}

public class Program
{
    public static async Task Main()
    {
        var generator = new ReportGenerator();
        using var cts = new CancellationTokenSource();

        cts.CancelAfter(250);

        try
        {
            await generator.GenerateHeavyReportAsync(cts.Token);
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine("[Client] Operasi berhasil dibatalkan secara elegan (Graceful Cancellation).");
        }
    }
}

